//! Auto-generated navigation page (openwiki's quickstart/index analog).
//! Index is derived state: regenerated on demand, never cited, excluded from
//! planning so it cannot generate its own refresh tasks.

use std::collections::BTreeMap;
use std::path::Path;

use loredex_core::{parse_wiki_links, Status, WikiPage};
use loredex_git::{GitRepo, GitView};

use crate::{check_page_with, load_pages, now_iso, pages_dir, Result};

pub const INDEX_ID: &str = "index";
pub const QUICKSTART_ID: &str = "quickstart";

/// Generated navigation pages: excluded from plans, evidence checks and lint.
pub fn is_generated(id: &str) -> bool {
    id == INDEX_ID || id == QUICKSTART_ID
}

const TYPE_ORDER: [&str; 5] = [
    "architecture",
    "workflow",
    "system",
    "integration",
    "testing",
];

/// Skeleton text for generated pages, selected by `[wiki] language`.
/// Protocol tokens (statuses, type names, command names) stay English on
/// purpose — they are identifiers agents grep for.
struct Skeleton {
    index_title: &'static str,
    index_h1: &'static str,
    index_note: &'static str,
    index_group_sep: &'static str,
    footer: &'static str, // {pages} {stale} {ts}
    evidence_word: &'static str,
    quickstart_title: &'static str,
    quickstart_h1: &'static str, // {repo} {index_id}
    quickstart_intro: &'static str,
    reading_path_h: &'static str,
    no_pages: &'static str,
    other_h: &'static str,
    protocol_h: &'static str,
    protocol_items: [&'static str; 3],
}

const EN: Skeleton = Skeleton {
    index_title: "Wiki index",
    index_h1: "# Repository wiki index",
    index_note: "Generated by `loredex index`. Navigation only, not evidence-backed.",
    index_group_sep: " — ",
    footer: "_{pages} page(s), {stale} stale, generated {ts}_",
    evidence_word: "evidence",
    quickstart_title: "Wiki quickstart",
    quickstart_h1: "# {repo} wiki — quickstart",
    quickstart_intro: "Generated navigation, not evidence-backed. Full catalog: [[wiki:{index_id}]].",
    reading_path_h: "## Recommended reading path",
    no_pages: "_No pages yet — run `loredex plan` and author the first module page._",
    other_h: "### other",
    protocol_h: "## How to use this wiki (agent protocol)",
    protocol_items: [
        "Call `wiki_check_freshness` (or `loredex check`) before trusting any page; treat stale pages as unverified and read the source.",
        "Audit claims with `wiki_get_evidence` — every citation resolves to the exact file content at current git HEAD.",
        "Keep the wiki fresh: `wiki_plan` lists what needs writing or repair; author with inline `[[cite:path:Lx-Ly]]` markers, one per claim; `wiki_refresh_page` auto-heals drifted citations.",
    ],
};

const ZH: Skeleton = Skeleton {
    index_title: "Wiki 索引",
    index_h1: "# 仓库 Wiki 索引",
    index_note: "由 `loredex index` 生成,仅用于导航,不作为源码证据。",
    index_group_sep: " —— ",
    footer: "_共 {pages} 页,{stale} 页过期,生成于 {ts}_",
    evidence_word: "证据",
    quickstart_title: "Wiki 快速入口",
    quickstart_h1: "# {repo} Wiki —— 快速入口",
    quickstart_intro: "生成的导航页,不作为源码证据;完整目录见 [[wiki:{index_id}]]。",
    reading_path_h: "## 推荐阅读路径",
    no_pages: "_还没有页面 —— 运行 `loredex plan`,先写下第一个模块页。_",
    other_h: "### 其他",
    protocol_h: "## 如何使用本 Wiki(agent 协议)",
    protocol_items: [
        "信任任何页面前先调用 `wiki_check_freshness`(或 `loredex check`);过期页面按未验证对待,直接读源码。",
        "用 `wiki_get_evidence` 核查论断 —— 每条引用都能解析到当前 git HEAD 上的精确文件内容。",
        "保持 wiki 新鲜:`wiki_plan` 列出待写/待修页面;写作时每条论断配一个行内 `[[cite:path:Lx-Ly]]` 标记;漂移的引用用 `wiki_refresh_page` 自愈。",
    ],
};

fn skeleton(wiki_dir: &Path) -> &'static Skeleton {
    match crate::config::locale(wiki_dir) {
        crate::config::Locale::En => &EN,
        crate::config::Locale::Zh => &ZH,
    }
}

fn fill(template: &str, key: &str, value: impl std::fmt::Display) -> String {
    template.replace(&format!("{{{key}}}"), &value.to_string())
}

/// Build index.md content grouped by top-level directory (or "top level"),
/// each line linking the page with live git freshness, never a plain text dump.
pub fn generate_index(repo: &GitRepo, wiki_dir: &Path) -> Result<Vec<WikiPage>> {
    generate_index_with(&repo.view(), wiki_dir)
}

pub fn generate_index_with(view: &GitView, wiki_dir: &Path) -> Result<Vec<WikiPage>> {
    let sk = skeleton(wiki_dir);
    let pages = load_pages(wiki_dir)?;
    crate::prime_view(view, &pages)?;
    let mut groups: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut stale_count = 0usize;
    let mut typed: Vec<(String, String, String)> = Vec::new(); // (type, id, title)
    for p in pages.iter().filter(|p| !is_generated(&p.meta.id)) {
        let live_stale = check_page_with(p, view)
            .map(|r| r.is_stale)
            .unwrap_or(false);
        if live_stale {
            stale_count += 1;
        }
        typed.push((
            p.meta.page_type.clone().unwrap_or_else(|| "other".into()),
            p.meta.id.clone(),
            p.meta.title.clone(),
        ));
        let group = match p.meta.id.split_once('/') {
            Some((head, _)) => head.to_string(),
            None => ".".to_string(),
        };
        let status = match (p.meta.status, live_stale) {
            (Status::Verified, false) => "verified",
            (_, true) => "STALE",
            (Status::Draft, _) => "draft",
            (Status::Stale, _) => "stale",
        };
        groups.entry(group).or_default().push(format!(
            "- [[wiki:{}]]{}{} _( {}, {} {}, type: {} )_",
            p.meta.id,
            sk.index_group_sep,
            p.meta.title,
            status,
            p.meta.evidence.len(),
            sk.evidence_word,
            p.meta.page_type.as_deref().unwrap_or("-")
        ));
    }
    let mut body = format!("{}\n\n{}\n\n", sk.index_h1, sk.index_note);
    for (group, lines) in groups {
        body.push_str(&format!("## {group}\n\n{}\n\n", lines.join("\n")));
    }
    let footer = sk
        .footer
        .replace(
            "{pages}",
            &pages
                .iter()
                .filter(|p| !is_generated(&p.meta.id))
                .count()
                .to_string(),
        )
        .replace("{stale}", &stale_count.to_string())
        .replace("{ts}", &now_iso());
    body.push_str(&format!("{footer}\n"));
    let head = view.head_commit().unwrap_or_default().to_string();
    let mk = |id: &str, title: &str, pt: &str, body: String| WikiPage {
        meta: loredex_core::PageMeta {
            id: id.into(),
            title: title.into(),
            status: Status::Verified,
            generated_at: now_iso(),
            commit: head.clone(),
            evidence: vec![],
            tags: vec!["generated".into()],
            page_type: Some(pt.into()),
        },
        body: body.into(),
        source_path: Some(pages_dir(wiki_dir).join(format!("{id}.md"))),
    };
    let index = mk(INDEX_ID, sk.index_title, "index", body);
    index.save_in_place()?;

    // quickstart: a guided reading path (openwiki's entry page analog)
    let repo_name = view
        .workdir()
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "this repository".into());
    let mut qs = format!(
        "{}\n\n{}\n\n{}\n\n",
        fill(sk.quickstart_h1, "repo", repo_name),
        fill(sk.quickstart_intro, "index_id", INDEX_ID),
        sk.reading_path_h
    );
    let mut listed = 0usize;
    for t in TYPE_ORDER {
        let mut items = Vec::new();
        for (pt, id, title) in &typed {
            if pt == t {
                items.push(format!("1. [[wiki:{id}]]{}{title}", sk.index_group_sep));
            }
        }
        if !items.is_empty() {
            qs.push_str(&format!("### {t}\n\n{}\n\n", items.join("\n")));
            listed += items.len();
        }
    }
    if listed == 0 {
        qs.push_str(sk.no_pages);
        qs.push_str("\n\n");
    }
    let others: Vec<String> = typed
        .iter()
        .filter(|(pt, _, _)| !TYPE_ORDER.contains(&pt.as_str()))
        .map(|(_, id, title)| format!("- [[wiki:{id}]]{}{title}", sk.index_group_sep))
        .collect();
    if !others.is_empty() {
        qs.push_str(sk.other_h);
        qs.push_str("\n\n");
        qs.push_str(&others.join("\n"));
        qs.push('\n');
    }
    qs.push_str(&format!("\n{}\n\n", sk.protocol_h));
    for (i, item) in sk.protocol_items.iter().enumerate() {
        qs.push_str(&format!("{}. {item}\n", i + 1));
    }
    let quickstart = mk(QUICKSTART_ID, sk.quickstart_title, "index", qs);
    quickstart.save_in_place()?;

    Ok(vec![index, quickstart])
}

/// Collect all [[wiki:id]] targets across pages (for lint).
pub fn all_wiki_links(wiki_dir: &Path) -> Result<Vec<(String, String)>> {
    let mut out = Vec::new();
    for p in load_pages(wiki_dir)? {
        for target in parse_wiki_links(&p.body) {
            out.push((p.meta.id.clone(), target));
        }
    }
    Ok(out)
}
